const assert=require('node:assert/strict');const {createRequire}=require('node:module');const {resolve}=require('node:path');const {randomUUID,randomBytes}=require('node:crypto');const {writeFileSync,mkdirSync}=require('node:fs');
assert.equal(process.env.CI,'true','Actions isolated HTTP fixture only');const url=new URL(process.env.DATABASE_URL);assert.equal(url.hostname,'127.0.0.1');assert.equal(url.port,'55432');assert.equal(url.pathname,'/qualification_training_teacher_ci');
const load=createRequire(resolve('server-version/backend/package.json'));load('tsx/cjs');const express=load('express');const {prisma}=load('./src/config/database.ts');const {generateToken}=load('./src/utils/jwt.ts');const {comparePassword}=load('./src/utils/password.ts');const {cacheService}=load('./src/services/cacheService.ts');
const passed=[];let server;
async function main(){
 await cacheService.initialize();const app=express();app.use(express.json());app.use('/api',load('./src/middleware/csrf.ts').csrfProtection);app.use('/api/users',load('./src/routes/users.ts').default);app.use('/api/auth',load('./src/routes/auth.ts').default);app.use('/api/teacher-codes',load('./src/routes/teacherCodes.ts').default);app.use((error,_req,res,_next)=>res.status(500).json({message:error.message}));
 server=app.listen(0,'127.0.0.1');await new Promise(r=>server.once('listening',r));const root=`http://127.0.0.1:${server.address().port}/api`,csrf=randomBytes(32).toString('hex');
 const actor=await prisma.user.create({data:{username:'http_admin_'+Date.now(),passwordHash:'synthetic-unusable',role:'STUDENT'}});await prisma.adminEntryGrant.create({data:{id:randomUUID(),userId:actor.id,entry:'TRAINING',grantedBy:actor.id}});
 const survey=await prisma.user.create({data:{username:'http_survey_'+Date.now(),passwordHash:'synthetic-unusable',role:'STUDENT'}});await prisma.adminEntryGrant.create({data:{id:randomUUID(),userId:survey.id,entry:'SURVEY',grantedBy:actor.id}});
 const teacher=await prisma.user.create({data:{username:'http_teacher_'+Date.now(),passwordHash:'synthetic-unusable',role:'TEACHER',teacherApproved:true,expiresAt:new Date('2020-01-01Z')}});
 const token=(u,age=0)=>generateToken({userId:u.id,username:u.username,role:u.role,accountDomain:'TRAINING',tokenVersion:u.tokenVersion,adminSessionId:'synthetic-proof',adminVerifiedAt:Date.now()/1000-age});const admin=token(actor),surveyToken=token(survey);
 async function request(path,{body,session=admin,csrfValid=true,method=body?'POST':'GET'}={}){const headers={'Content-Type':'application/json',Cookie:`ptool_csrf=${csrf}${session?`; ptool_session=${session}`:''}`};if(csrfValid)headers['x-csrf-token']=csrf;const res=await fetch(root+path,{method,headers,body:body?JSON.stringify(body):undefined});return {status:res.status,data:await res.json(),headers:res.headers}}
 const target=()=>prisma.user.findUniqueOrThrow({where:{id:teacher.id}}),path='/users/'+teacher.id+'/training-management';const cmd=async(action,extra={})=>({action,expectedUpdatedAt:(await target()).updatedAt.toISOString(),...extra});
 assert.equal((await request(path,{body:await cmd('FREEZE'),session:null})).status,401);passed.push('anonymous denied');
 assert.equal((await request(path,{body:await cmd('FREEZE'),csrfValid:false})).status,403);passed.push('CSRF required');
 assert.equal((await request(path,{body:await cmd('FREEZE'),session:surveyToken})).status,403);passed.push('Survey admin cannot manage Training');
 const staleMfa=await request(path,{body:await cmd('FREEZE'),session:token(actor,301)});assert.equal(staleMfa.data.code,'ADMIN_KEY_STEP_UP_REQUIRED');passed.push('recent MFA required');
 const start=Date.now(),renew=await request(path,{body:await cmd('EXTEND',{months:3})});assert.equal(renew.status,200);assert(new Date(renew.data.data.expiresAt).getTime()>start+80*86400000);passed.push('expired HTTP renewal starts now');
 const old=await target(),oldBody=await cmd('FREEZE'),oldToken=token(old);assert.equal((await request(path,{body:oldBody})).status,200);assert.equal((await request('/users/me',{session:oldToken})).status,401);assert.equal((await request(path,{body:oldBody})).status,409);passed.push('freeze revokes old session and stale writes');
 assert.equal((await request(path,{body:await cmd('UNFREEZE')})).status,200);assert.equal((await request('/users/me',{session:oldToken})).status,401);passed.push('unfreeze does not revive old session');
 const grant=await prisma.adminEntryGrant.create({data:{id:randomUUID(),userId:teacher.id,entry:'SURVEY',grantedBy:actor.id}});assert.equal((await request(path,{body:await cmd('RESET_PASSWORD')})).status,403);await prisma.adminEntryGrant.update({where:{id:grant.id},data:{revokedAt:new Date(),revokedBy:actor.id}});passed.push('management targets protected');
 const beforeReset=token(await target()),reset=await request(path,{body:await cmd('RESET_PASSWORD')});assert.equal(reset.status,200);assert.match(reset.headers.get('cache-control'),/no-store/);let row=await target();assert(row.mustChangePassword);assert(await comparePassword(reset.data.data.temporaryPassword,row.passwordHash));assert.equal((await request('/users/me',{session:beforeReset})).status,401);assert.equal((await request('/users/me',{session:token(row)})).status,403);passed.push('temporary password response and forced password change');
 const code=await request('/teacher-codes',{body:{maxUses:1,expiresAt:new Date(Date.now()+86400000).toISOString(),accountValidityDays:90}});assert.equal(code.status,200);const registered=await request('/auth/teacher-register',{body:{teacherCode:code.data.data.code,username:'reg'+Date.now(),nickname:'合成培训师',password:'SyntheticPassword123'}});assert.equal(registered.status,200);row=await prisma.user.findUniqueOrThrow({where:{id:registered.data.data.user.id}});assert.equal(row.teacherApproved,false);assert(row.expiresAt.getTime()>Date.now()+89*86400000);passed.push('HTTP registration carries administrator account term');
 mkdirSync('training-teacher-evidence',{recursive:true});writeFileSync('training-teacher-evidence/http.json',JSON.stringify({kind:'fresh-isolated-http-assertions',passed,credentialsPersistedInReport:false},null,2)+'\n');console.log(JSON.stringify({httpContracts:passed.length,passed}));
}
main().then(async()=>{await prisma.$disconnect();server?.close();process.exit(0)}).catch(async error=>{console.error(error.message);await prisma.$disconnect();server?.close();process.exit(1)});
